mkuse!{use crate :: Span ;}
mkitem!{mkenum!{# [doc = " An enum representing a diagnostic level."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] # [derive (Copy , Clone , Debug)] # [non_exhaustive] pub enum Level { # [doc = " An error."] Error , # [doc = " A warning."] Warning , # [doc = " A note."] Note , # [doc = " A help message."] Help , }}}
mkitem!{mktrait!{# [doc = " Trait implemented by types that can be converted into a set of `Span`s."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub trait MultiSpan { # [doc = " Converts `self` into a `Vec<Span>`."] fn into_spans (self) -> Vec < Span > ; }}}
mkitem!{mkimpl!{# [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] impl MultiSpan for Span { fn into_spans (self) -> Vec < Span > { vec ! [self] } }}}
mkitem!{mkimpl!{# [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] impl MultiSpan for Vec < Span > { fn into_spans (self) -> Vec < Span > { self } }}}
mkitem!{mkimpl!{# [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] impl < 'a > MultiSpan for & 'a [Span] { fn into_spans (self) -> Vec < Span > { self . to_vec () } }}}
mkitem!{mkstruct!{# [doc = " A structure representing a diagnostic message and associated children"] # [doc = " messages."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] # [derive (Clone , Debug)] pub struct Diagnostic { level : Level , message : String , spans : Vec < Span > , children : Vec < Diagnostic > , }}}
mkitem!{macro_rules ! diagnostic_child_methods { ($ spanned : ident , $ regular : ident , $ level : expr) => { # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] # [doc = concat ! ("Adds a new child diagnostics message to `self` with the [`" , stringify ! ($ level) , "`] level, and the given `spans` and `message`.")] pub fn $ spanned < S , T > (mut self , spans : S , message : T) -> Diagnostic where S : MultiSpan , T : Into < String >, { self . children . push (Diagnostic :: spanned (spans , $ level , message)) ; self } # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] # [doc = concat ! ("Adds a new child diagnostic message to `self` with the [`" , stringify ! ($ level) , "`] level, and the given `message`.")] pub fn $ regular < T : Into < String >> (mut self , message : T) -> Diagnostic { self . children . push (Diagnostic :: new ($ level , message)) ; self } } ; }}
mkitem!{mkstruct!{# [doc = " Iterator over the children diagnostics of a `Diagnostic`."] # [derive (Debug , Clone)] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub struct Children < 'a > (std :: slice :: Iter < 'a , Diagnostic >) ;}}
mkitem!{mkimpl!{# [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] impl < 'a > Iterator for Children < 'a > { type Item = & 'a Diagnostic ; fn next (& mut self) -> Option < Self :: Item > { self . 0 . next () } }}}
mkitem!{mkimpl!{# [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] impl Diagnostic { # [doc = " Creates a new diagnostic with the given `level` and `message`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn new < T : Into < String > > (level : Level , message : T) -> Diagnostic { Diagnostic { level , message : message . into () , spans : vec ! [] , children : vec ! [] } } # [doc = " Creates a new diagnostic with the given `level` and `message` pointing to"] # [doc = " the given set of `spans`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn spanned < S , T > (spans : S , level : Level , message : T) -> Diagnostic where S : MultiSpan , T : Into < String > , { Diagnostic { level , message : message . into () , spans : spans . into_spans () , children : vec ! [] } } diagnostic_child_methods ! (span_error , error , Level :: Error) ; diagnostic_child_methods ! (span_warning , warning , Level :: Warning) ; diagnostic_child_methods ! (span_note , note , Level :: Note) ; diagnostic_child_methods ! (span_help , help , Level :: Help) ; # [doc = " Returns the diagnostic `level` for `self`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn level (& self) -> Level { self . level } # [doc = " Sets the level in `self` to `level`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn set_level (& mut self , level : Level) { self . level = level ; } # [doc = " Returns the message in `self`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn message (& self) -> & str { & self . message } # [doc = " Sets the message in `self` to `message`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn set_message < T : Into < String > > (& mut self , message : T) { self . message = message . into () ; } # [doc = " Returns the `Span`s in `self`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn spans (& self) -> & [Span] { & self . spans } # [doc = " Sets the `Span`s in `self` to `spans`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn set_spans < S : MultiSpan > (& mut self , spans : S) { self . spans = spans . into_spans () ; } # [doc = " Returns an iterator over the children diagnostics of `self`."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn children (& self) -> Children < '_ > { Children (self . children . iter ()) } # [doc = " Emit the diagnostic."] # [unstable (feature = "proc_macro_diagnostic" , issue = "54140")] pub fn emit (self) { fn to_internal (diag : Diagnostic) -> crate :: bridge :: Diagnostic < crate :: bridge :: client :: Span > { crate :: bridge :: Diagnostic { level : diag . level , message : diag . message , spans : diag . spans . into_iter () . map (| s | s . 0) . collect () , children : diag . children . into_iter () . map (to_internal) . collect () , } } crate :: bridge :: client :: FreeFunctions :: emit_diagnostic (to_internal (self)) ; } }}}